package server

import "crypto/subtle"

func secureCompare(a,b string) bool { return subtle.ConstantTimeCompare([]byte(a),[]byte(b))==1 }

const dashboardHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>NekoSune Radio</title><style>
:root{color-scheme:dark;--bg:#070d0b;--panel:#101a16;--line:#274337;--sub:#94b3a5;--accent:#66e0a0;--white:#f1fff7}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 12% -8%,#163b2b,transparent 48%),var(--bg);color:var(--white);font:15px/1.55 system-ui,Segoe UI,sans-serif}
header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px max(24px,calc((100vw - 1260px)/2));border-bottom:1px solid var(--line)}
.brand{font-weight:800;font-size:22px;letter-spacing:-.5px}.brand span{color:var(--accent)}nav a{color:var(--sub);margin-left:22px;text-decoration:none}nav a:hover{color:var(--white)}
main{max-width:1300px;margin:auto;padding:38px 24px 90px}.eyebrow{color:var(--accent);font-size:11px;letter-spacing:2.8px;font-weight:800;text-transform:uppercase}h1{font-size:clamp(36px,5vw,62px);letter-spacing:-2px;line-height:1.1;margin:14px 0}h2{font-size:23px;letter-spacing:-.5px}.intro{max-width:620px;color:var(--sub);font-size:17px}
.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:30px 0}.metric,.card,.panel{background:linear-gradient(150deg,#14221b,#0c1411);border:1px solid var(--line);border-radius:15px}.metric{padding:18px 23px}.metric strong{font-size:32px;display:block;color:var(--accent)}.metric small{color:var(--sub);font-size:12px;text-transform:uppercase;letter-spacing:1px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:17px}.card{overflow:hidden;padding:16px}.card-top{display:flex;gap:15px;align-items:center}.cover{width:82px;height:82px;flex:none;border-radius:10px;background:linear-gradient(120deg,#194c34,#1b302d);object-fit:cover}.name{font-weight:800;font-size:18px}.genre{color:var(--sub);font-size:12px}.now{margin:16px 0;min-height:45px}.now b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.now small{color:var(--sub)}
.actions{display:flex;align-items:center;gap:9px}.pill{margin-left:auto;color:var(--accent);font-size:12px}.offline{color:#fbad8c}.button{cursor:pointer;border:1px solid #3c6c50;background:#193b2b;border-radius:9px;color:var(--white);padding:9px 14px;font-weight:700}.button:hover{background:#265b3e}.secondary{background:transparent;border-color:var(--line);color:var(--sub)}.button:disabled{opacity:.35;cursor:not-allowed}
.panel{padding:25px;margin-top:23px}.bar{height:9px;background:#203128;border-radius:20px;overflow:hidden;margin:5px 0 16px}.bar i{display:block;height:100%;background:linear-gradient(90deg,#3db77a,#8ef4b6)}.country-row{display:flex;justify-content:space-between}.muted{color:var(--sub)}input{font:inherit;padding:11px;border-radius:9px;border:1px solid #39684e;color:white;background:#0a1510;max-width:100%;width:100%}label{display:block;margin:10px 0 5px}.admin-row{padding:17px 0;border-bottom:1px solid var(--line);display:flex;gap:18px;align-items:center;flex-wrap:wrap}.admin-row strong{min-width:180px}.admin-row .muted{flex:1}form{display:flex;gap:8px;flex-wrap:wrap;align-items:center}form input{width:240px}.hidden{display:none!important}#notice{min-height:25px;color:var(--accent)}audio{display:none}
@media(max-width:640px){header{padding:16px 20px}main{padding:24px 17px}.metrics{grid-template-columns:1fr 1fr}.metric:last-child{grid-column:span 2}.grid{grid-template-columns:1fr}form input{width:100%}}
</style></head><body><header><div class="brand">Neko<span>Sune</span> Radio <span style="font-weight:400;font-size:12px">● LIVE</span></div><nav><a href="/">Listen</a><a href="/admin">Admin</a></nav></header><main>
<section id="public"><div class="eyebrow">YOUR MUSIC, YOUR FREQUENCY</div><h1>The sound of NekoSune.</h1><p class="intro">Discover independent music stations, tune in instantly, and see what's playing across our network. No account needed to listen.</p>
<div class="metrics"><div class="metric"><strong id="total">–</strong><small>Listening now</small></div><div class="metric"><strong id="stationcount">–</strong><small>Radio stations</small></div><div class="metric"><strong id="tracks">–</strong><small>Tracks in rotation</small></div></div>
<h2>Explore radio stations <span class="muted" style="font-size:12px;font-weight:normal">Auto-updating</span></h2><div id="stations" class="grid"><p class="muted">Loading stations…</p></div>
<section class="panel"><div class="eyebrow">GLOBAL AUDIENCE</div><h2>Where people are tuning in</h2><p class="muted">Aggregated listening statistics, when enabled on the server. No listener IP addresses are displayed.</p><div id="countries" class="muted">Loading statistics…</div></section></section>
<section id="admin" class="hidden"><div class="eyebrow">PRIVATE CONTROL CENTER</div><h1>Radio management.</h1><p class="intro">Control your station availability and upload new music without touching Docker files directly.</p>
<div id="login" class="panel"><h2>Admin access</h2><label for="password">Admin API password</label><input id="password" type="password" autocomplete="current-password" placeholder="Password from config.toml"><p><button id="signin" class="button">Sign in</button></p></div>
<div id="controls" class="panel hidden"><div style="display:flex;justify-content:space-between;align-items:center"><h2>Manage stations</h2><button class="button secondary" id="logout">Sign out</button></div><div id="adminstations"></div><p class="muted">Uploads are saved to the music directory. Newly uploaded tracks enter the broadcast playlist after a cliamp-server restart. Stop/start only controls new stream connections, not the encoder process.</p></div><p id="notice"></p></section>
</main><audio id="player" controls></audio><script>
const $=id=>document.getElementById(id), isAdmin=location.pathname==="/admin";
$("public").classList.toggle("hidden",isAdmin);$("admin").classList.toggle("hidden",!isAdmin);
let lastStations=[],playing="",artCache=new Map(),secret=sessionStorage.getItem("radio_admin")||"";
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function notify(message){$("notice").textContent=message}
async function artwork(song, img){if(!song.artist&&!song.album)return;const key=song.artist+" "+(song.album||song.title);if(artCache.has(key)){img.src=artCache.get(key);return}
try{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),4000);const query=new URLSearchParams({term:key,entity:"song",limit:"1"});const r=await fetch("https://itunes.apple.com/search?"+query,{signal:controller.signal});clearTimeout(timeout);if(!r.ok)return;const data=await r.json();const cover=data.results&&data.results[0]&&data.results[0].artworkUrl100;if(cover){const url=cover.replace("100x100bb","300x300bb");artCache.set(key,url);img.src=url}}catch(e){}}
function card(st){const c=el("article","card"),top=el("div","card-top"),img=el("img","cover");img.alt="Album artwork";img.loading="lazy";img.referrerPolicy="no-referrer";top.append(img);let heading=el("div");heading.append(el("div","name",st.name),el("div","genre",st.genre||"Independent radio"));top.append(heading);c.append(top);
const now=el("div","now");now.append(el("b","",st.current_track.title||"On air"),el("small","",st.current_track.artist||"Discover new music"));c.append(now);artwork(st.current_track,img);
const actions=el("div","actions"),btn=el("button","button",playing===st.id?"■ Stop":"▶ Listen");btn.disabled=!st.online;btn.onclick=()=>{if(playing===st.id){$("player").pause();$("player").removeAttribute("src");playing=""}else{$("player").src=st.stream;$("player").play().catch(()=>{});playing=st.id}renderStations(lastStations)};actions.append(btn);
const copy=el("button","button secondary","Copy link");copy.onclick=()=>navigator.clipboard.writeText(location.origin+st.stream);actions.append(copy);
const count=el("span","pill"+(st.online?"":" offline"),st.online?st.listeners+" listening":"Offline");actions.append(count);c.append(actions);return c}
function renderStations(stations){const container=$("stations");container.replaceChildren();for(const st of stations)container.append(card(st));if(!stations.length)container.append(el("p","muted","No stations found"))}
async function refreshPublic(){try{const res=await fetch("/api/public/radio",{cache:"no-store"});if(!res.ok)throw Error("API unavailable");const data=await res.json();lastStations=data.stations||[];$("total").textContent=data.total_listeners??0;$("stationcount").textContent=lastStations.length;$("tracks").textContent=lastStations.reduce((n,s)=>n+s.tracks,0);renderStations(lastStations)}catch(e){$("stations").textContent="Unable to load radio stations. "+e.message}}
async function refreshCountries(){try{const r=await fetch("/statistics");if(!r.ok)throw Error();const d=await r.json(),totals={};for(const s of Object.values(d.stations||{})){for(const row of s.top_countries||[])totals[row.country]=(totals[row.country]||0)+(row.sessions||0)}const entries=Object.entries(totals).sort((a,b)=>b[1]-a[1]).slice(0,10);const root=$("countries");root.replaceChildren();if(!entries.length){root.textContent="Location statistics not yet available.";return}for(const [country,value] of entries){const label=el("div","country-row");label.append(el("span","",country),el("span","",String(value)));root.append(label);const bar=el("div","bar"),fill=el("i");fill.style.width=(100*value/entries[0][1])+"%";bar.append(fill);root.append(bar)}}catch(e){$("countries").textContent="Enable [stats] and [geo] in config.toml to show country statistics."}}
async function api(path,options={}){options.headers={...(options.headers||{}),Authorization:"Bearer "+secret};const r=await fetch(path,options);if(!r.ok)throw Error((await r.text()).slice(0,160));return r.json()}
async function refreshAdmin(){try{const rows=await api("/api/admin/stations");$("login").classList.add("hidden");$("controls").classList.remove("hidden");$("adminstations").replaceChildren();for(const st of rows){const row=el("div","admin-row");row.append(el("strong","",st.name));row.append(el("span","muted",st.listeners+" connections · "+st.path));const toggle=el("button","button",st.online?"Stop station":"Start station");toggle.onclick=async()=>{try{await api("/api/admin/stations/"+encodeURIComponent(st.id)+"/state",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({online:!st.online})});notify(st.name+" updated");refreshAdmin()}catch(e){notify(e.message)}};row.append(toggle);const form=el("form");const input=el("input");input.type="file";input.name="file";input.accept=".mp3,.flac,.wav,.ogg,.opus,.aac,.m4a,.webm,.wma";const submit=el("button","button secondary","Upload music");submit.type="submit";form.append(input,submit);form.onsubmit=async e=>{e.preventDefault();if(!input.files[0])return;const fd=new FormData();fd.append("file",input.files[0]);submit.disabled=true;notify("Uploading "+input.files[0].name+"…");try{const answer=await api("/api/admin/stations/"+encodeURIComponent(st.id)+"/upload",{method:"POST",body:fd});notify(answer.message)}catch(e){notify(e.message)}finally{submit.disabled=false}};row.append(form);$("adminstations").append(row)}notify("")}catch(e){$("controls").classList.add("hidden");$("login").classList.remove("hidden");notify("Authentication or server error: "+e.message)}}
$("signin").onclick=()=>{secret=$("password").value;sessionStorage.setItem("radio_admin",secret);refreshAdmin()};
$("logout").onclick=()=>{secret="";sessionStorage.removeItem("radio_admin");$("login").classList.remove("hidden");$("controls").classList.add("hidden");notify("")};
if(isAdmin){if(secret)refreshAdmin()}else{refreshPublic();refreshCountries();setInterval(refreshPublic,10000);setInterval(refreshCountries,60000)}
</script></body></html>`
